//! The engine's requests timed in this process (W1b measurements), the counterpart of the
//! browser's engine worker checks (`scripts/web-engine.mjs`, `src/web/check.ts`):
//!
//!   cargo run --release -p oc-engine --example bench [-- <workers>]
//!   node scripts/wasm.mjs cargo run --release --target wasm32-unknown-emscripten -p oc-engine --example bench
//!
//! The corpus rebuilt through `engine_rebuild` (a fresh engine, in name order), a cached
//! rebuild of `block-hole` (its round trip without the transport), and every corpus part at
//! once in one assembly: regenerated by the engine alone, then (natively) on `<workers>` worker
//! threads (default 4), first and three times warm (cache cleared). Prints `BENCH {...}`.
use std::path::Path;
use std::sync::Arc;
use std::time::Instant;

use oc_asm::Assembler;
use oc_engine::engine::{Engine, MeshStore};
use oc_engine::request::{request, Answer};
use oc_kernel_occt::OcctKernel;
use serde_json::{json, Value};

fn engine(workers: usize) -> Engine {
    let mut a = Assembler::new(OcctKernel::default());
    a.workers = workers;
    Engine::new(a, Arc::new(MeshStore::default()), None)
}

fn ms(t: Instant) -> f64 {
    (t.elapsed().as_secs_f64() * 1e4).round() / 10.0
}

fn ask(e: &mut Engine, cmd: &str, a: Value) -> Answer {
    request(e, cmd, a).unwrap_or_else(|m| panic!("{cmd}: {m}"))
}

fn median(mut v: Vec<f64>) -> f64 {
    v.sort_by(f64::total_cmp);
    (v[v.len() / 2] * 1e3).round() / 1e3
}

fn main() {
    let workers: usize = std::env::args().nth(1).and_then(|a| a.parse().ok()).unwrap_or(4);
    let corpus = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../corpus");
    let mut names: Vec<String> = std::fs::read_dir(&corpus)
        .unwrap()
        .filter_map(|e| e.ok()?.path().file_name()?.to_str()?.strip_suffix(".ocpart").map(String::from))
        .collect();
    names.sort();
    let docs: Vec<Value> = names.iter().map(|n| serde_json::from_str(&std::fs::read_to_string(corpus.join(format!("{n}.ocpart"))).unwrap()).unwrap()).collect();

    // The corpus through requests, as the browser's check rebuilds it.
    let mut e = engine(1);
    let t = Instant::now();
    for d in &docs {
        ask(&mut e, "engine_rebuild", json!({ "features": d["features"], "quality": 3 }));
    }
    let corpus_ms = ms(t);
    let block = &docs[names.iter().position(|n| n == "block-hole").unwrap()]["features"];
    let cached: Vec<f64> = (0..100)
        .map(|_| {
            let t = Instant::now();
            ask(&mut e, "engine_rebuild", json!({ "features": block, "quality": 3 }));
            t.elapsed().as_secs_f64() * 1e3
        })
        .collect();

    // Every corpus part at once, side by side.
    let doc = json!({
        "format": "opencad-assembly", "version": 2, "name": "all", "units": "MMGS",
        "components": names.iter().enumerate().map(|(i, n)| json!({ "id": format!("c{i}"), "kind": "part", "path": format!("{n}.ocpart"), "config": "Default" })).collect::<Vec<_>>(),
        "instances": names.iter().enumerate().map(|(i, n)| json!({ "id": format!("i{i}"), "component": format!("c{i}"), "name": format!("{n}<1>"), "fixed": true, "transform": { "position": [i as f64 * 150.0, 0, 0], "rotation": [1, 0, 0, 0] } })).collect::<Vec<_>>(),
        "mates": [],
    });
    let args = json!({ "doc": doc, "path": corpus.join("all.ocasm").to_string_lossy(), "lightweight": false, "quality": 3 });
    let all = |w: usize| {
        let mut e = engine(w);
        let mut times = vec![];
        for i in 0..4 {
            if i > 0 {
                ask(&mut e, "engine_clear_cache", Value::Null);
            }
            let t = Instant::now();
            let Answer::Bytes(b) = ask(&mut e, "asm_build", args.clone()) else { panic!("not a build reply") };
            times.push(ms(t));
            let n = u32::from_le_bytes(b[4..8].try_into().unwrap()) as usize;
            let h: Value = serde_json::from_slice(&b[8..8 + n]).unwrap();
            assert_eq!(h["regenerated"].as_u64(), Some(names.len() as u64));
        }
        json!({ "firstMs": times[0], "warmMs": &times[1..] })
    };
    let mut report = json!({
        "target": std::env::consts::ARCH,
        "occt": format!("{} {}", oc_kernel_occt::OCCT_VERSION, oc_kernel_occt::OCCT_LINKAGE),
        "corpusMs": corpus_ms,
        "cachedRebuildMedianMs": median(cached),
        "parts": names.len(),
        "engineAlone": all(1),
    });
    if oc_asm::parallel::THREADS {
        report["threads"] = json!({ "workers": workers, "run": all(workers) });
    }
    println!("BENCH {report}");
}
